# Run in the signed-in user's session, where Store apps and WinGet are registered.
$ErrorActionPreference = 'Stop'
$logDir = Join-Path $env:LOCALAPPDATA 'Cyberwin'
New-Item -ItemType Directory -Path $logDir -Force | Out-Null
$log = Join-Path $logDir 'apps.log'
Start-Transcript -Path $log -Append | Out-Null
$shortcut = Join-Path ([Environment]::GetFolderPath('Desktop')) 'Finish Cyberwin setup.lnk'
$failed = $false
function Test-Edge {
    foreach ($base in @($env:ProgramFiles, ${env:ProgramFiles(x86)}, $env:LOCALAPPDATA)) {
        if ($base -and (Test-Path (Join-Path $base 'Microsoft\Edge\Application\msedge.exe'))) { return $true }
    }
    return $false
}
$apps = @(
    @{ Name = 'Paint'; Package = 'Microsoft.Paint'; Id = '9PCFS5B6T72H'; Source = 'msstore' },
    @{ Name = 'Photos'; Package = 'Microsoft.Windows.Photos'; Id = '9WZDNCRFJBH4'; Source = 'msstore' },
    @{ Name = 'Edge'; Package = ''; Id = 'Microsoft.Edge'; Source = 'winget' }
)
function Test-App($app) {
    if ($app.Name -eq 'Edge') { return (Test-Edge) }
    return [bool](Get-AppxPackage -Name $app.Package -ErrorAction SilentlyContinue)
}
try {
    $missing = @($apps | Where-Object { -not (Test-App $_) })
    if ($missing.Count -gt 0) {
        if (-not (Get-Command winget.exe -ErrorAction SilentlyContinue)) {
            Add-AppxPackage -RegisterByFamilyName -MainPackage Microsoft.DesktopAppInstaller_8wekyb3d8bbwe -ErrorAction Continue
            for ($i = 0; $i -lt 10; $i++) {
                if (Get-Command winget.exe -ErrorAction SilentlyContinue) { break }
                Start-Sleep -Seconds 3
            }
        }
        $winget = Get-Command winget.exe -ErrorAction SilentlyContinue
        if (-not $winget) { throw 'App Installer/WinGet is unavailable. Install App Installer from Microsoft Store, then run the desktop shortcut.' }
        foreach ($app in $missing) {
            Write-Output "Installing $($app.Name)..."
            & $winget.Source install --id $app.Id --exact --source $app.Source --accept-source-agreements --accept-package-agreements --disable-interactivity
            $code = $LASTEXITCODE
            for ($i = 0; $i -lt 10; $i++) {
                if (Test-App $app) { break }
                Start-Sleep -Seconds 2
            }
            if (-not (Test-App $app)) {
                $failed = $true
                Write-Warning "$($app.Name) is missing after installation (exit $code)."
            }
        }
    }
    foreach ($app in $apps) {
        $present = Test-App $app
        Write-Output "$($app.Name): $present"
        if (-not $present) { $failed = $true }
    }
} catch {
    $failed = $true
    Write-Warning $_.Exception.Message
} finally {
    Stop-Transcript | Out-Null
}
if ($failed) {
    $shell = New-Object -ComObject WScript.Shell
    $link = $shell.CreateShortcut($shortcut)
    $link.TargetPath = "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe"
    $link.Arguments = '-NoProfile -ExecutionPolicy Bypass -File "C:\Windows\Setup\Scripts\ensure-apps.ps1"'
    $link.Save()
    $shell.Popup("Cyberwin setup needs attention. Connect to the internet and run 'Finish Cyberwin setup' on your desktop. Log: $log", 30, 'Cyberwin apps', 48) | Out-Null
    exit 1
}
if (Test-Path -LiteralPath $shortcut) { Remove-Item -LiteralPath $shortcut }
exit 0
